"""v2.66: is ker π (the ideal of kQ generated by the class differences a − a′; π the collapse kQ → kQ^s) stable under
every fold? Lemma R′ (docs v2.66 §3.3): if P(ker π) ⊆ ker π then πPι is a fold of kQ^s with the vertex block of P.
The property is invariant under the census group and the weightings (both commute with π), so G-orbit
representatives suffice. Pickles are loaded with a restricted unpickler (numpy arrays only).
Usage: python3 -I analysis/v2_66_kerpi.py QUIVER QS PICKLE [PICKLE …]   (census --save-reps or --save-folds output)"""
import sys, os, pickle, collections
import numpy as np
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
import pcensus as pc
OK = {('numpy._core.numeric', '_frombuffer'), ('numpy', 'dtype'), ('numpy._core.multiarray', '_reconstruct'), ('numpy', 'ndarray'),
      ('numpy.core.numeric', '_frombuffer'), ('numpy.core.multiarray', '_reconstruct')}
class SafeU(pickle.Unpickler):
    def find_class(self, mod, name):
        if (mod, name) in OK: return super().find_class(mod, name)
        raise pickle.UnpicklingError(f"blocked {mod}.{name}")
Q, QS = sys.argv[1], sys.argv[2]
nv, A = pc.QUIVERS[Q]; nvs, As = pc.QUIVERS[QS]
B, M, D = pc.build(nv, A); Bs, _, _ = pc.build(nvs, As)
cls = {st: i for i, st in enumerate(As)}
pmap = lambda b: b if b[0] == 'v' else ('p', tuple(cls[A[a]] for a in b[1]))
fib = collections.defaultdict(list)
for i, b in enumerate(B): fib[pmap(b)].append(i)
d = len(B); Kpi = []
for f in fib.values():
    for j in f[1:]:
        v = np.zeros(d, dtype=np.int64); v[j] = 1; v[f[0]] = -1; Kpi.append(v)
Kpi = np.array(Kpi).T if Kpi else np.zeros((d, 0), dtype=np.int64)
Pi = np.zeros((len(Bs), d), dtype=np.int64)
for i, b in enumerate(B): Pi[Bs.index(pmap(b)), i] = 1
vid = [i for i, b in enumerate(B) if b[0] == 'v']
for fn in sys.argv[3:]:
    R = SafeU(open(fn, 'rb')).load(); p = R['p']; assert list(map(tuple, R['basis'])) == list(map(tuple, B)) if 'basis' in R else True
    mats = R['greps'] if 'greps' in R else R['folds']
    good = bad = 0; badV = set(); goodV = set()
    for P in mats:
        P = np.asarray(P, dtype=np.int64).reshape(d, d) % p
        V = tuple(map(tuple, ((P[np.ix_(vid, vid)] + 1) % p - 1).tolist()))
        if ((Pi @ P @ Kpi) % p == 0).all(): good += 1; goodV.add(V)
        else: bad += 1; badV.add(V)
    print(f"{Q} q = {p} ({os.path.basename(fn)}): {good + bad} folds/reps; P(ker π) ⊆ ker π for {good}, not for {bad}; "
          f"blocks {len(goodV | badV)}, blocks with some stable fold {len(goodV)}, blocks with only unstable folds {len(badV - goodV)}")
